mapper.select:
SELECT inquiry_id, title, content, writer, created_at, updated_at, status AS inquiryStatus, inquiry_pwd AS inquiryPwd FROM Inquiry WHERE status = 'AVAILABLE'
AND title LIKE CONCAT('%', #{keyword}, '%')
ORDER BY created_at DESC LIMIT #{size} OFFSET #{offset}

mapper.update:
UPDATE Inquiry
SET title = #{title},
    content = #{content},
    updated_at = NOW()
WHERE inquiry_id = #{inquiryId}
AND inquiry_pwd = #{inquiryPwd}

UPDATE Inquiry
SET status = 'DELETED'
WHERE inquiry_id = #{inquiryId}
AND inquiry_pwd = #{inquiryPwd}
